public abstract class GeneratedCurrentImportRateExtractorBase {

	public static final String COMPONENT_NAME = "CurrentImportRateExtractor";

	protected static final String AGILERATESJSON_TOPIC = "agile-rates";
	protected static final String AGILERATESJSON_SLOT = "json";

	@Inject
	protected ComponentService componentService;

	@Inject
	protected TopicSlotService topicSlotService;

	@PostConstruct
	public void registerGeneratedComponent() {
		componentService.ensureExists(COMPONENT_NAME);
	}

	@Scheduled(fixedRate = "30m", initialDelay = "30m")
	public void recomputeEveryThirtyMinutes() {
		trigger();
	}

	public void trigger() {
		Optional<String> agileRatesJsonValue =
		topicSlotService.getTextValue(
			AGILERATESJSON_TOPIC,
			AGILERATESJSON_SLOT);

			if (agileRatesJsonValue.isEmpty()) {
				return;
			}

			activate(agileRatesJsonValue.get());
		}

		protected abstract void activate(String agileRatesJson);
	}